UPDATE pms_sku_stock
SET
stock = CASE id

    WHEN #{item.productSkuId} THEN stock - #{item.productQuantity}

END,
lock_stock = CASE id

    WHEN #{item.productSkuId} THEN lock_stock - #{item.productQuantity}

END
WHERE id IN

    #{item.productSkuId}

UPDATE pms_sku_stock
SET lock_stock = lock_stock + #{quantity}
WHERE id = #{skuId}
  AND stock - lock_stock >= #{quantity}

